    async function mount(d) {
        const w = document.getElementById('phwrap');
        if (!w || !d)
            return;
        const old = document.getElementById('phf');
        if (old)
            old.remove();
        if (window.__phMsg) {
            removeEventListener('message', window.__phMsg);
            window.__phMsg = null;
        }
        clearTimeout(window.__phT);
        const ld = document.getElementById('phload'), fb = document.getElementById('phfall');
        if (ld) {
            ld.style.display = 'grid';
            ld.textContent = '⏳ تجهيز المحاكاة العلمية…';
        }
        if (fb) {
            fb.style.display = 'none';
            fb.innerHTML = '';
        }
        /* صندوق معزول: صفحة phet-frame.html داخل sandbox دون allow-same-origin (أصلها null) — لا ترى تخزين الموقع ولها سياسة أمان خاصة */
        const f = document.createElement('iframe');
        f.id = 'phf';
        f.title = d.n || 'محاكاة علمية';
        f.loading = 'eager';
        f.referrerPolicy = 'no-referrer';
        f.setAttribute('sandbox', 'allow-scripts allow-pointer-lock');
        f.setAttribute('allow', 'fullscreen; autoplay');
        const done = () => { if (ld)
            ld.style.display = 'none'; };
        const localBtn = () => { const lb = fb && fb.querySelector('#ph-local-fallback'); if (lb)
            lb.onclick = () => { const frame = document.getElementById('phf'); if (frame)
                frame.remove(); fb.style.display = 'none'; if (ld)
                ld.style.display = 'none'; mountLocalFallback(d, w); }; const rb = fb && fb.querySelector('#ph-retry'); if (rb)
            rb.onclick = () => mount(d); };
        const fail = why => { done(); f.style.visibility = 'hidden'; if (!fb)
            return; fb.style.display = 'flex'; fb.innerHTML = '<span>⚠️ تعذّر تشغيل هذه المحاكاة على جهازك' + (why ? ' (' + why + ')' : '') + '. جرّب إعادة المحاولة، أو شغّل النموذج المحلي البديل.</span> <button type="button" class="btn g" id="ph-retry">↺ إعادة المحاولة</button> <button type="button" class="btn g" id="ph-local-fallback">تشغيل النموذج المحلي</button>'; localBtn(); };
        let html = null;
        if (has(d.k)) {
            try {
                const h = await getHtml(d.k);
                if (!w.isConnected || !document.getElementById('phstage'))
                    return;
                if (h)
                    html = rebrandEmbeddedSimulation(h);
            }
            catch (e) {
                if (ld)
                    ld.textContent = 'تعذّر فك الحزمة المضمنة؛ يمكنك تشغيل النموذج المحلي.';
            }
        }
        if (!html) {
            if (ld)
                ld.style.display = 'none';
            if (fb)
                fb.style.display = 'block';
            mountLocalFallback(d, w);
            return;
        }
        if (!w.isConnected)
            return;
        let started = false, loaded = false, lastErr = '';
        const onMsg = e => {
            if (e.source !== f.contentWindow)
                return;
            const m = e.data || {};
            if (m.type === 'vlab-phet-ready') {
                try {
                    f.contentWindow.postMessage({ type: 'vlab-phet-html', html: html }, '*');
                }
                catch (x) {
                    fail('');
                }
            }
            else if (m.type === 'vlab-phet-loaded') {
                loaded = true;
                setTimeout(done, 180);
            }
            else if (m.type === 'vlab-phet-started') {
                started = true;
                f.style.visibility = '';
                done();
                if (fb && /تعذّر تشغيل/.test(fb.textContent)) {
                    fb.style.display = 'none';
                    fb.innerHTML = '';
                }
            }
            else if (m.type === 'vlab-phet-error') {
                lastErr = String(m.msg || '').slice(0, 120);
            }
        };
        window.__phMsg = onMsg;
        addEventListener('message', onMsg);
        f.src = '/phet-frame.html';
        w.appendChild(f);
        window.__phT = setTimeout(() => { if (!started && document.getElementById('phf') === f)
            fail(loaded ? '' : 'لم تكتمل'); }, 25000);
    }
